const sealWaldoConversationEpisode = `-- name: SealWaldoConversationEpisode :execrows
UPDATE waldo_conversation_episodes
SET state = 'sealed', sealed_at = ?, seal_reason = ?
WHERE id = ? AND conversation_id = ? AND state = 'active'
`

type SealWaldoConversationEpisodeParams struct {
	SealedAt       sql.NullTime
	SealReason     string
	ID             string
	ConversationID string
}

func (q *Queries) SealWaldoConversationEpisode(ctx context.Context, arg SealWaldoConversationEpisodeParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, sealWaldoConversationEpisode,
		arg.SealedAt,
		arg.SealReason,
		arg.ID,
		arg.ConversationID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
